/// Transposes a rectangular matrix: rows become columns.
pub fn transpose(m: List[List[Int]]) -> List[List[Int]] {
  let width = match m.first() {
    Some(row) => row.len(),
    None => 0,
  }
  var out: List[List[Int]] = []
  for j in range(0, width) {
    let col = j
    let column = m.map(fn(row) => row.get_or(col, 0))
    out = out.push(column)
  }
  return out
}
